def moving_average(data, num_points):
    moving_average_list = []
    for i in range(0, len(data)-num_points+1):
        window_sum = 0
        for j in range(i, i+num_points):
            window_sum += data[j]
        moving_average_list.append(window_sum/num_points)
    return moving_average_list

